(5879831, 855801, 2279, '<td valign="top">I like your shot, it has a wow factor to it, but its hard to figure out what the focal point is. I can''t tell if its the metal object in the foreground or the really big set of columns behind it. I imagine its the foreground. I think this could have stood out more if the object didn''t end overlapping the big object behind it. Its also left side heavy with both objects taking up the left side and also both leading the eye out of the image and away from the unnoticed right side. Good work though. 6</td>', 'I like your shot, it has a wow factor to it, but its hard to figure out what the focal point is. I can''t tell if its the metal object in the foreground or the really big set of columns behind it. I imagine its the foreground. I think this could have stood out more if the object didn''t end overlapping the big object behind it. Its also left side heavy with both objects taking up the left side and also both leading the eye out of the image and away from the unnoticed right side. Good work though. 6', '2010-02-24 19:00:51.000000', NULL, 1),
(5879833, 855753, 2279, '<td valign="top">Awesome contrast using a Triad color harmony of yellow/orange, red/violet and green/blue. I only wish it was a little brighter and maybe you came back and showed a little more of the wheel section. 7</td>', 'Awesome contrast using a Triad color harmony of yellow/orange, red/violet and green/blue. I only wish it was a little brighter and maybe you came back and showed a little more of the wheel section. 7', '2010-02-24 19:03:35.000000', NULL, 1),
(5879839, 855856, 2279, '<td valign="top">The color is nice but its contrast is still making the eye go straight towards the flower because the knome isnt saturated enough and the large birdhouse is drab and blends with the rocks and foreground orange color. 5</td>', 'The color is nice but its contrast is still making the eye go straight towards the flower because the knome isnt saturated enough and the large birdhouse is drab and blends with the rocks and foreground orange color. 5', '2010-02-24 19:08:03.000000', NULL, 1),
(5879841, 856047, 2279, '<td valign="top">I love the background and the yellow moody color use but I wish the right flower wasn''t cropped out and I have to knock you for the subject matter being flowers. 4</td>', 'I love the background and the yellow moody color use but I wish the right flower wasn''t cropped out and I have to knock you for the subject matter being flowers. 4', '2010-02-24 19:09:31.000000', NULL, 1),
(5879844, 855929, 2279, '<td valign="top">Very nice focus on the tomatos and the dew drops are crystal clear. Great use of complementery contrast between the greens and reds and for personal use I would clone out some of the outer elements which are . Good job. 8</td>', 'Very nice focus on the tomatos and the dew drops are crystal clear. Great use of complementery contrast between the greens and reds and for personal use I would clone out some of the outer elements which are . Good job. 8', '2010-02-24 19:12:42.000000', NULL, 1),
(5879846, 855903, 2279, '<td valign="top">Its a great captured moment but the composition is dead centered and has the green and that white distracting element. 5</td>', 'Its a great captured moment but the composition is dead centered and has the green and that white distracting element. 5', '2010-02-24 19:14:23.000000', NULL, 1),
(5879849, 855381, 48268, '<td valign="top">I love this, but the focus seems a little soft.</td>', 'I love this, but the focus seems a little soft.', '2010-02-24 19:16:49.000000', NULL, 1),
(5879889, 856117, 2279, '<td valign="top">Nice sharp focus. Color is amazing as well. I would suggest that for personal use you clone out those two white spots, they really stand out. 8</td>', 'Nice sharp focus. Color is amazing as well. I would suggest that for personal use you clone out those two white spots, they really stand out. 8', '2010-02-24 19:35:02.000000', NULL, 1),
(5879906, 855416, 106922, '<td valign="top">I like this.A very simple but beautiful Shot.I really like the reflected sky as well.Nice work,Alan</td>', 'I like this.A very simple but beautiful Shot.I really like the reflected sky as well.Nice work,Alan', '2010-02-24 19:39:30.000000', NULL, 1),
(5879908, 855378, 2279, '<td valign="top">This image is nice but its sooo busy. Between the bright green leaves, grasshopper, flower and butterfly its hard to find a main subject in your shot. The color is nice but that bright red is contrasting more than the butterfly which is actually pretty dark which would make the flower your main subject. 5</td>', 'This image is nice but its sooo busy. Between the bright green leaves, grasshopper, flower and butterfly its hard to find a main subject in your shot. The color is nice but that bright red is contrasting more than the butterfly which is actually pretty dark which would make the flower your main subject. 5', '2010-02-24 19:39:47.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5879915, 854866, 2279, '<td valign="top">Looks more like a park than a garden but I like how the lines of the table, the fence and the horizon line all lead your eye to the only splash of color the playground. It looks a little underexposed though. That snow is looking more grey than white. 5</td>', 'Looks more like a park than a garden but I like how the lines of the table, the fence and the horizon line all lead your eye to the only splash of color the playground. It looks a little underexposed though. That snow is looking more grey than white. 5', '2010-02-24 19:42:21.000000', NULL, 1),
(5879934, 855484, 2279, '<td valign="top">Nice dof and contrast between the ladybug and green sprout. The red border is competing with the ladybug though its trying to pull my eyes away from the subject. 8</td>', 'Nice dof and contrast between the ladybug and green sprout. The red border is competing with the ladybug though its trying to pull my eyes away from the subject. 8', '2010-02-24 19:47:54.000000', NULL, 1),
(5879946, 855487, 48268, '<td valign="top">I find the fact that the focus on the thumb is soft to be very distracting - otherwise I''d have given this a 10.</td>', 'I find the fact that the focus on the thumb is soft to be very distracting - otherwise I''d have given this a 10.', '2010-02-24 19:50:21.000000', NULL, 1),
(5879958, 855620, 2279, '<td valign="top">I love the colors and and how crisp the moss looks and the details of the snail but there is too much negative space for me. Your subject and really only important part of the image is so small in the corner. When I decide to look at the rest of the image I keep seeing a blurry nose and sunglasses and your image shouldn''t say that. 5</td>', 'I love the colors and and how crisp the moss looks and the details of the snail but there is too much negative space for me. Your subject and really only important part of the image is so small in the corner. When I decide to look at the rest of the image I keep seeing a blurry nose and sunglasses and your image shouldn''t say that. 5', '2010-02-24 19:52:28.000000', NULL, 1),
(5879959, 855050, 7743, '<td valign="top">Nice capture but unless I''m mistaken the main suject here is a flower.</td>', 'Nice capture but unless I''m mistaken the main suject here is a flower.', '2010-02-24 19:52:53.000000', NULL, 1),
(5879968, 856251, 2279, '<td valign="top">Wow I love the contrast of this and the sharpness of the hairs. For personal use I would clone out the upper white dot and also the one that touches the tip of the spike. Overall great job. 8</td>', 'Wow I love the contrast of this and the sharpness of the hairs. For personal use I would clone out the upper white dot and also the one that touches the tip of the spike. Overall great job. 8', '2010-02-24 19:57:18.000000', NULL, 1),
(5879980, 855567, 2279, '<td valign="top">Wow thats an interesting looking beetle. Great focus on the eyes and clever composition. 8</td>', 'Wow thats an interesting looking beetle. Great focus on the eyes and clever composition. 8', '2010-02-24 20:02:12.000000', NULL, 1),
(5879985, 855666, 2279, '<td valign="top">Thats a nice flower shot and I like the balance of the two other buds but this flower is definately the main subject matter of this shot. 2</td>', 'Thats a nice flower shot and I like the balance of the two other buds but this flower is definately the main subject matter of this shot. 2', '2010-02-24 20:04:03.000000', NULL, 1),
(5879990, 855438, 2279, '<td valign="top">I like the repeating use of reds between the berries and the blurry red ones on the far right, it balances your composition. 7</td>', 'I like the repeating use of reds between the berries and the blurry red ones on the far right, it balances your composition. 7', '2010-02-24 20:06:42.000000', NULL, 1),
(5880001, 855573, 48268, '<td valign="top">Nice!</td>', 'Nice!', '2010-02-24 20:10:34.000000', NULL, 1),
(5880003, 856284, 2279, '<td valign="top">Yay dirt. 4</td>', 'Yay dirt. 4', '2010-02-24 20:11:30.000000', NULL, 1),
(5880008, 855050, 2279, '<td valign="top">Yay Flowers! 3</td>', 'Yay Flowers! 3', '2010-02-24 20:11:47.000000', NULL, 1),
(5880034, 856128, 2279, '<td valign="top">Thats a beautiful composition. I love how the wavy hills lead your eye to the towers in the middle. The only thing is it looks a little overexposed on the side of the towers facing the sun. 8</td>', 'Thats a beautiful composition. I love how the wavy hills lead your eye to the towers in the middle. The only thing is it looks a little overexposed on the side of the towers facing the sun. 8', '2010-02-24 20:17:04.000000', NULL, 1),
(5880040, 854864, 2279, '<td valign="top">"In the Garden" and "No flowers". This is a photo of a flower not in a garden. 3</td>', '"In the Garden" and "No flowers". This is a photo of a flower not in a garden. 3', '2010-02-24 20:19:28.000000', NULL, 1),
(5880086, 855711, 2279, '<td valign="top">Very, very nice. Colors are amazing and keeps the eye moving between the bee and the flowerish thing. I do think that without the border there would be too much negative space and your eye would wander away. (Good thing you added the border). 8.</td>', 'Very, very nice. Colors are amazing and keeps the eye moving between the bee and the flowerish thing. I do think that without the border there would be too much negative space and your eye would wander away. (Good thing you added the border). 8.', '2010-02-24 20:32:33.000000', NULL, 1),
(5880187, 856318, 114763, '<td valign="top">ha!</td>', 'ha!', '2010-02-24 20:54:31.000000', NULL, 1),
(5880260, 855382, 114128, '<td valign="top">so pretty!! a little soft though, but still a 9 :)</td>', 'so pretty!! a little soft though, but still a 9 :)', '2010-02-24 22:08:18.000000', NULL, 1),
(5880291, 855666, 81362, '<td valign="top">Nice flower as main subject. Probably won''t get scores to match image quality because of the second part of the challenge details: "... Here''s the catch... the main subject of your photograph may NOT be a flower." Not voting just now. Apologies if this duplicates other comments.</td>', 'Nice flower as main subject. Probably won''t get scores to match image quality because of the second part of the challenge details: "... Here''s the catch... the main subject of your photograph may NOT be a flower." Not voting just now. Apologies if this duplicates other comments.', '2010-02-24 22:51:07.000000', NULL, 1),
(5880374, 855815, 98422, '<td valign="top">Sharp as a pin</td>', 'Sharp as a pin', '2010-02-25 01:29:25.000000', NULL, 1),
(5880375, 854864, 98422, '<td valign="top">Don''t think the main subject can be a flower but nice shot anyway.</td>', 'Don''t think the main subject can be a flower but nice shot anyway.', '2010-02-25 01:30:51.000000', NULL, 1),
(5880376, 855416, 98422, '<td valign="top">Simple but really effective.          Lovely shot</td>', 'Simple but really effective.          Lovely shot', '2010-02-25 01:35:14.000000', NULL, 1),
(5880419, 855666, 69368, '<td valign="top">... the main subject of your photograph may NOT be a flower....</td>', '... the main subject of your photograph may NOT be a flower....', '2010-02-25 03:09:31.000000', NULL, 1),
(5880428, 856113, 88718, '<td valign="top">The photo is striking but it could have been straightened a little</td>', 'The photo is striking but it could have been straightened a little', '2010-02-25 03:27:12.000000', NULL, 1),
(5880429, 855666, 88718, '<td valign="top">Nice shot but this looks decidedly like a flower to me</td>', 'Nice shot but this looks decidedly like a flower to me', '2010-02-25 03:31:17.000000', NULL, 1),
(5880430, 854864, 88718, '<td valign="top">Nice shot but this looks decidedly like a flower to me</td>', 'Nice shot but this looks decidedly like a flower to me', '2010-02-25 03:31:41.000000', NULL, 1),
(5880451, 854981, 64086, '<td valign="top">Very nice shot. I like the texture of the tree, the flow from the rock down to the tree and back up the branch on the right.(parallel to hazy distant horizon.) I think the composition would be improved further if the angle were just slightly different so that the left branch had some seperation from the rock. I''d also like to see a color version or a bit more contrast to the B&amp;W processing.</td>', 'Very nice shot. I like the texture of the tree, the flow from the rock down to the tree and back up the branch on the right.(parallel to hazy distant horizon.) I think the composition would be improved further if the angle were just slightly different so that the left branch had some seperation from the rock. I''d also like to see a color version or a bit more contrast to the B&W processing.', '2010-02-25 06:00:25.000000', NULL, 1),
(5880497, 855914, 56254, '<td valign="top">I have that same lantern ... if I hadn''t put it in the garage it would be buried in snow!  Don''t you just love the rustiness?!</td>', 'I have that same lantern ... if I hadn''t put it in the garage it would be buried in snow!  Don''t you just love the rustiness?!', '2010-02-25 08:12:48.000000', NULL, 1),
(5880583, 856152, 30049, '<td valign="top">Finally, a real garden!  Hooray.  Even I didn''t have one available this time of year.  :-)</td>', 'Finally, a real garden!  Hooray.  Even I didn''t have one available this time of year.  :-)', '2010-02-25 10:23:01.000000', NULL, 1),
(5880595, 855573, 6667, '<td valign="top">Over the top.  One of the most interesting images in a long time!  I know, however, there will be those that consider it an asinine shot.  (Sorry.  Could not resist.)  Very best of luck 8</td>', 'Over the top.  One of the most interesting images in a long time!  I know, however, there will be those that consider it an asinine shot.  (Sorry.  Could not resist.)  Very best of luck 8', '2010-02-25 10:36:09.000000', NULL, 1),
(5880597, 856099, 6667, '<td valign="top">Came back to up this one a notch on my scale. Nicely done. BOL 8</td>', 'Came back to up this one a notch on my scale. Nicely done. BOL 8', '2010-02-25 10:36:46.000000', NULL, 1),
(5880936, 854960, 28427, '<td valign="top">Already mowing your lawn? Here it doesn''t even grow yet.  I think that within 8 tot 10 weeks it''ll start again.  Nice sharp photograph.</td>', 'Already mowing your lawn? Here it doesn''t even grow yet.  I think that within 8 tot 10 weeks it''ll start again.  Nice sharp photograph.', '2010-02-25 16:23:19.000000', NULL, 1),
(5880938, 856012, 28427, '<td valign="top">Original approach of the challenge team and well executed *9*</td>', 'Original approach of the challenge team and well executed *9*', '2010-02-25 16:24:02.000000', NULL, 1),
(5880946, 855567, 28427, '<td valign="top">Amazingly detailed *10*</td>', 'Amazingly detailed *10*', '2010-02-25 16:31:35.000000', NULL, 1),
(5880957, 854804, 28427, '<td valign="top">Beautiful colour scheme, DOF and focus are exactly where they have to be *8*</td>', 'Beautiful colour scheme, DOF and focus are exactly where they have to be *8*', '2010-02-25 16:41:59.000000', NULL, 1),
(5880965, 856237, 28427, '<td valign="top">Less is more, this photograph doesn''t need anything else or more.  *9*</td>', 'Less is more, this photograph doesn''t need anything else or more.  *9*', '2010-02-25 16:52:40.000000', NULL, 1),
(5881138, 856226, 10785, '<td valign="top">I voted this photo somewhat low and wanted to leave a comment. I just thought it was lacking in color and composition. It shows the time of the season accurately, but there is no punch or nothing real interesting. One thing I could suggest would be to get up real close on one of the tall grasses and use a wide open DoF to show the texture of the grass and the chaotic lines of each blade. Hope that was helpful.</td>', 'I voted this photo somewhat low and wanted to leave a comment. I just thought it was lacking in color and composition. It shows the time of the season accurately, but there is no punch or nothing real interesting. One thing I could suggest would be to get up real close on one of the tall grasses and use a wide open DoF to show the texture of the grass and the chaotic lines of each blade. Hope that was helpful.', '2010-02-25 20:05:05.000000', NULL, 1),
(5881156, 855981, 10785, '<td valign="top">The focus really should have been on the water drop, if that was the subject. Here the focus in in the upper rightcorner of the photo which seems somewhat odd.</td>', 'The focus really should have been on the water drop, if that was the subject. Here the focus in in the upper rightcorner of the photo which seems somewhat odd.', '2010-02-25 20:15:52.000000', NULL, 1),
(5881160, 856183, 10785, '<td valign="top">Hooray for the lensbaby!! I like this shot. Good use of selective focus however it could have been right on the hand. It is somewhat above the hand which is still ok because the focus is nice and sharp. Very good pp of color with the orange.</td>', 'Hooray for the lensbaby!! I like this shot. Good use of selective focus however it could have been right on the hand. It is somewhat above the hand which is still ok because the focus is nice and sharp. Very good pp of color with the orange.', '2010-02-25 20:17:47.000000', NULL, 1),
(5881164, 856019, 10785, '<td valign="top">I don''t really think using the Rule of Thirds really added anything to this photo composition wise. In fact my eye tends to dwell the out of focus area on the right rather than locking in on the lantern. Other wise you did a great job with the B&amp;W conversion and the DoF and exposure are real good.</td>', 'I don''t really think using the Rule of Thirds really added anything to this photo composition wise. In fact my eye tends to dwell the out of focus area on the right rather than locking in on the lantern. Other wise you did a great job with the B&W conversion and the DoF and exposure are real good.', '2010-02-25 20:21:15.000000', NULL, 1),
(5881172, 855666, 10785, '<td valign="top">A little hard to vote low on this because it is a nice shot. However you did fail to follow the instructions of the challenge. If I was the client and you had the scope of work for this photo shoot as detailed, I would not pay for the work and I probably wouldn''t call again for future work. Great shot though! TOo bad...</td>', 'A little hard to vote low on this because it is a nice shot. However you did fail to follow the instructions of the challenge. If I was the client and you had the scope of work for this photo shoot as detailed, I would not pay for the work and I probably wouldn''t call again for future work. Great shot though! TOo bad...', '2010-02-25 20:26:18.000000', NULL, 1),
(5881176, 854864, 10785, '<td valign="top">I''m very sorry... It''s a little hard to vote low on this because it is a nice shot. However you did fail to follow the instructions of the challenge. If I was the client and you had the scope of work for this photo shoot as detailed, I would not pay for the work and I probably wouldn''t call again for future work. Great shot though! Too bad...</td>', 'I''m very sorry... It''s a little hard to vote low on this because it is a nice shot. However you did fail to follow the instructions of the challenge. If I was the client and you had the scope of work for this photo shoot as detailed, I would not pay for the work and I probably wouldn''t call again for future work. Great shot though! Too bad...', '2010-02-25 20:29:44.000000', NULL, 1),
(5881178, 856047, 10785, '<td valign="top">It''s so difficult to vote on this because of the specific instructions given in the challenge details. If I was the client and you presented me with this photo given the scope of work for this photo shoot as detailed, I would not pay for the work and I probably wouldn''t call again for future work.</td>', 'It''s so difficult to vote on this because of the specific instructions given in the challenge details. If I was the client and you presented me with this photo given the scope of work for this photo shoot as detailed, I would not pay for the work and I probably wouldn''t call again for future work.', '2010-02-25 20:32:47.000000', NULL, 1),
(5881180, 855381, 10785, '<td valign="top">Great use of soft focus to add a sense of nostalgia to this picture. It really gives a sense of the serenity and peace the artist must feel from playing his flute. With the shot coming from behind the front hedge in the foreground, it seems to give a sense that we are peeking in on a private moment.</td>', 'Great use of soft focus to add a sense of nostalgia to this picture. It really gives a sense of the serenity and peace the artist must feel from playing his flute. With the shot coming from behind the front hedge in the foreground, it seems to give a sense that we are peeking in on a private moment.', '2010-02-25 20:36:11.000000', NULL, 1),
(5881182, 856132, 10785, '<td valign="top">THid dhot really made me dizzy.</td>', 'THid dhot really made me dizzy.', '2010-02-25 20:39:31.000000', NULL, 1),
(5881183, 856317, 10785, '<td valign="top">Adding a little child on the bench or a person of any type would have really added to this shot.</td>', 'Adding a little child on the bench or a person of any type would have really added to this shot.', '2010-02-25 20:40:27.000000', NULL, 1),
(5881184, 855847, 10785, '<td valign="top">This bug is fierce and the shot feels like it is ripped right from the pages of NatGeo. Well done. There is nothing I can add about the technical details of the shot. Everything looks great as far as exposure, focus, composition, etc.</td>', 'This bug is fierce and the shot feels like it is ripped right from the pages of NatGeo. Well done. There is nothing I can add about the technical details of the shot. Everything looks great as far as exposure, focus, composition, etc.', '2010-02-25 20:42:58.000000', NULL, 1),
(5881187, 855487, 10785, '<td valign="top">I really like the subject and the message sent. I don''t know if it was possible to work around but the thumb in the foreground being out of focus is really distracting. Perhaps a more open hand with palm upward or even downward sort of reaching but not quite ready to pick the apple would have helped. Very nice touch with the small serpent in the background. I almost missed it.</td>', 'I really like the subject and the message sent. I don''t know if it was possible to work around but the thumb in the foreground being out of focus is really distracting. Perhaps a more open hand with palm upward or even downward sort of reaching but not quite ready to pick the apple would have helped. Very nice touch with the small serpent in the background. I almost missed it.', '2010-02-25 20:45:55.000000', NULL, 1),
(5881190, 856206, 10785, '<td valign="top">Very good subject. The shot is well composed. It does suffer from being somewhat gray. There isn''t much luminescense to the shot meaning the red color does not realy pop.</td>', 'Very good subject. The shot is well composed. It does suffer from being somewhat gray. There isn''t much luminescense to the shot meaning the red color does not realy pop.', '2010-02-25 20:52:43.000000', NULL, 1),
(5881192, 855071, 10785, '<td valign="top">There is a blue hue to this shot which may mean the white balance was not set properly. Instead of the snow being white and reflecting the sunlight it seems to be blue and absorbing the light. Other than that I think exploring the different angles of the subject could help reveal something more intersting to show about it.</td>', 'There is a blue hue to this shot which may mean the white balance was not set properly. Instead of the snow being white and reflecting the sunlight it seems to be blue and absorbing the light. Other than that I think exploring the different angles of the subject could help reveal something more intersting to show about it.', '2010-02-25 20:56:26.000000', NULL, 1),
(5881199, 856022, 10785, '<td valign="top">I''m not too sure how you can make a picture of the dirt very interesting... using a somewhat biblical reference in the title didn''t really add to it because there doesn''t appear to be any seed in the shot. Perhaps with some sprouts, it could be made better. I work with dirt every day and you did manage to get the color very accurate.</td>', 'I''m not too sure how you can make a picture of the dirt very interesting... using a somewhat biblical reference in the title didn''t really add to it because there doesn''t appear to be any seed in the shot. Perhaps with some sprouts, it could be made better. I work with dirt every day and you did manage to get the color very accurate.', '2010-02-25 20:59:38.000000', NULL, 1),
(5881200, 856284, 10785, '<td valign="top">I am just not sure that you can get a shot of dirt to look very interesting. You did manage to show what appears to be potting soil very accurately as far as color and texture. This appears very wet.</td>', 'I am just not sure that you can get a shot of dirt to look very interesting. You did manage to show what appears to be potting soil very accurately as far as color and texture. This appears very wet.', '2010-02-25 21:00:50.000000', NULL, 1),
(5881201, 855934, 10785, '<td valign="top">This is a good shot and composed very well. You did a great job with the depth of field but seem to have missed the focus.</td>', 'This is a good shot and composed very well. You did a great job with the depth of field but seem to have missed the focus.', '2010-02-25 21:02:12.000000', NULL, 1),
(5881230, 855872, 57447, '<td valign="top">Nice close up.</td>', 'Nice close up.', '2010-02-25 21:46:03.000000', NULL, 1),
(5881232, 856105, 57447, '<td valign="top">Now that''s close.</td>', 'Now that''s close.', '2010-02-25 21:47:11.000000', NULL, 1),
(5881238, 855593, 57447, '<td valign="top">Spring''s just around the corner:)</td>', 'Spring''s just around the corner:)', '2010-02-25 21:51:48.000000', NULL, 1),
(5881240, 855633, 57447, '<td valign="top">This is unique.</td>', 'This is unique.', '2010-02-25 21:52:18.000000', NULL, 1),
(5881242, 855201, 57447, '<td valign="top">Good shot, a ND filter might have made it stand out even more.</td>', 'Good shot, a ND filter might have made it stand out even more.', '2010-02-25 21:53:55.000000', NULL, 1),
(5881260, 855558, 66855, '<td valign="top">i like the composition, and the subject, but my first impression is that my eyes are not sure where to go</td>', 'i like the composition, and the subject, but my first impression is that my eyes are not sure where to go', '2010-02-25 22:25:16.000000', NULL, 1),
(5881261, 855438, 66855, '<td valign="top">this is really a lovely photograph, I wish i could tell a little bit more about whats happening in the background on the right.</td>', 'this is really a lovely photograph, I wish i could tell a little bit more about whats happening in the background on the right.', '2010-02-25 22:27:03.000000', NULL, 1),
(5881262, 855978, 66855, '<td valign="top">beautiful photo</td>', 'beautiful photo', '2010-02-25 22:28:07.000000', NULL, 1),
(5881263, 856247, 66855, '<td valign="top">i love the color of the leaves, but i wish there was a little more contrast with the tree.</td>', 'i love the color of the leaves, but i wish there was a little more contrast with the tree.', '2010-02-25 22:30:23.000000', NULL, 1),
(5881271, 855856, 66855, '<td valign="top">its a nice photograph... my eyes want to drift to the flower but they dont really seem to settle on any particular thing.  The gnome is a little over exposed.</td>', 'its a nice photograph... my eyes want to drift to the flower but they dont really seem to settle on any particular thing.  The gnome is a little over exposed.', '2010-02-25 22:35:15.000000', NULL, 1),
(5881275, 855177, 66855, '<td valign="top">Its a nice photo, I hope the young lady''s name is Rosemary.  However, my eyes kind of gravitate to the over exposed parts of her clothing, and her face.</td>', 'Its a nice photo, I hope the young lady''s name is Rosemary.  However, my eyes kind of gravitate to the over exposed parts of her clothing, and her face.', '2010-02-25 22:37:50.000000', NULL, 1),
(5881279, 856179, 66855, '<td valign="top">Well balanced, exposure and colors are nice, however for me, it makes me feel like I am in a studio, and not a garden.</td>', 'Well balanced, exposure and colors are nice, however for me, it makes me feel like I am in a studio, and not a garden.', '2010-02-25 22:40:00.000000', NULL, 1),
