(5886237, 855556, 108580, '<td valign="top">Nice and close and well spotted but horribly OOF.</td>', 'Nice and close and well spotted but horribly OOF.', '2010-03-02 01:01:54.000000', NULL, 1),
(5886241, 855981, 108580, '<td valign="top">The dew drops are OOF but the top RHS is. I think you missed it here.</td>', 'The dew drops are OOF but the top RHS is. I think you missed it here.', '2010-03-02 01:02:55.000000', NULL, 1),
(5886245, 856289, 108580, '<td valign="top">I would shoot lower and use your lens wide open to create a more appealing closer image of the frog with BG OOF adding to some sort of mood.</td>', 'I would shoot lower and use your lens wide open to create a more appealing closer image of the frog with BG OOF adding to some sort of mood.', '2010-03-02 01:04:21.000000', NULL, 1),
(5886248, 856132, 108580, '<td valign="top">DMC (Does meet challenge) but I''d try be more creative with the items and the composition.</td>', 'DMC (Does meet challenge) but I''d try be more creative with the items and the composition.', '2010-03-02 01:05:22.000000', NULL, 1),
(5886249, 856316, 108580, '<td valign="top">Your garden is a corn field? I think this is a stretch. The sepia tone you have given this doesn''t work inmo, sorry. Perhaps B&amp;W.</td>', 'Your garden is a corn field? I think this is a stretch. The sepia tone you have given this doesn''t work inmo, sorry. Perhaps B&W.', '2010-03-02 01:07:02.000000', NULL, 1),
(5886252, 856184, 108580, '<td valign="top">Nope. Sorry</td>', 'Nope. Sorry', '2010-03-02 01:07:53.000000', NULL, 1),
(5886256, 855801, 108580, '<td valign="top">Could be a great composition if only the BG were OOF. Use aperture control and open your lens up to f/5.6 or f/8 or so to just get the sundial in focus.</td>', 'Could be a great composition if only the BG were OOF. Use aperture control and open your lens up to f/5.6 or f/8 or so to just get the sundial in focus.', '2010-03-02 01:09:14.000000', NULL, 1),
(5886257, 856142, 108580, '<td valign="top">DMC (Does meet challenge) but no primary subject or theme o attract my attention.</td>', 'DMC (Does meet challenge) but no primary subject or theme o attract my attention.', '2010-03-02 01:09:51.000000', NULL, 1),
(5886260, 855816, 108580, '<td valign="top">It could well be in your garden but it''s not inspiring or interesting to me sorry.</td>', 'It could well be in your garden but it''s not inspiring or interesting to me sorry.', '2010-03-02 01:10:32.000000', NULL, 1),
(5886264, 856039, 108580, '<td valign="top">Interesting find. I could be wrong but it looks flipped. The BG is still in too much focus. Perhaps a shallower DOF would have given more appeal?</td>', 'Interesting find. I could be wrong but it looks flipped. The BG is still in too much focus. Perhaps a shallower DOF would have given more appeal?', '2010-03-02 01:12:12.000000', NULL, 1),
(5886268, 856103, 108580, '<td valign="top">Bit of a stretch but I suppose it could be if you lived in a basement :)</td>', 'Bit of a stretch but I suppose it could be if you lived in a basement :)', '2010-03-02 01:12:57.000000', NULL, 1),
(5886270, 855389, 108580, '<td valign="top">I think you tried to go semi-abstract here? If only that diagonal white bar had of been removed it would be more appealing.</td>', 'I think you tried to go semi-abstract here? If only that diagonal white bar had of been removed it would be more appealing.', '2010-03-02 01:14:03.000000', NULL, 1),
(5886272, 856247, 108580, '<td valign="top">Odd coloured leaves (ivy?). Almost as if the WB is off. I would have use the bark only as my background to improve the texture and feel of the image.</td>', 'Odd coloured leaves (ivy?). Almost as if the WB is off. I would have use the bark only as my background to improve the texture and feel of the image.', '2010-03-02 01:15:19.000000', NULL, 1),
(5886275, 855593, 108580, '<td valign="top">Hah a copycat! Off course you know theres another image in the challenge like this. I think your perspective is too high leaving the subjects struggling for recognition. Go closer!</td>', 'Hah a copycat! Off course you know theres another image in the challenge like this. I think your perspective is too high leaving the subjects struggling for recognition. Go closer!', '2010-03-02 01:16:18.000000', NULL, 1),
(5886279, 855949, 108580, '<td valign="top">Moody and well spotted, reflection in water, nice sky. Try landscape orientation next time for more impact. the leading lines and angle you shot this should go on forever into the distance, ala landscape orientation.</td>', 'Moody and well spotted, reflection in water, nice sky. Try landscape orientation next time for more impact. the leading lines and angle you shot this should go on forever into the distance, ala landscape orientation.', '2010-03-02 01:18:02.000000', NULL, 1),
(5886280, 856112, 108580, '<td valign="top">Fun shot.</td>', 'Fun shot.', '2010-03-02 01:18:30.000000', NULL, 1),
(5886281, 855003, 108580, '<td valign="top">Nice image but an ND2 filter may have given more depth, and the runners would be blurred adding a bit more interest.</td>', 'Nice image but an ND2 filter may have given more depth, and the runners would be blurred adding a bit more interest.', '2010-03-02 01:19:30.000000', NULL, 1),
(5886285, 854960, 108580, '<td valign="top">I can''t comment this. It''s just a close picture of an old lawnmower on the grass. Sorry</td>', 'I can''t comment this. It''s just a close picture of an old lawnmower on the grass. Sorry', '2010-03-02 01:20:44.000000', NULL, 1),
(5886288, 856118, 108580, '<td valign="top">The leading lines are good, exposure is acceptable. Subject is dead boring sorry.</td>', 'The leading lines are good, exposure is acceptable. Subject is dead boring sorry.', '2010-03-02 01:21:38.000000', NULL, 1),
(5886290, 855558, 108580, '<td valign="top">Great attempt at a dark seedy forlorn moody image. I would like to see the tombstone a bit more.</td>', 'Great attempt at a dark seedy forlorn moody image. I would like to see the tombstone a bit more.', '2010-03-02 01:22:41.000000', NULL, 1),
(5886293, 856307, 108580, '<td valign="top">I don''t think plant matter can read but what do I know :)</td>', 'I don''t think plant matter can read but what do I know :)', '2010-03-02 01:23:11.000000', NULL, 1),
(5886295, 856318, 108580, '<td valign="top">How would he get in?</td>', 'How would he get in?', '2010-03-02 01:23:30.000000', NULL, 1),
(5886297, 855902, 108580, '<td valign="top">The tree or the building? I don''t get it sorry.</td>', 'The tree or the building? I don''t get it sorry.', '2010-03-02 01:24:01.000000', NULL, 1),
(5886300, 856110, 108580, '<td valign="top">Nice capture. It is however OE by at least 1 stop.  There is some CA going on in your glass. Try using curves in PS to improve the image''s contrast.</td>', 'Nice capture. It is however OE by at least 1 stop.  There is some CA going on in your glass. Try using curves in PS to improve the image''s contrast.', '2010-03-02 01:25:27.000000', NULL, 1),
(5886301, 855563, 108580, '<td valign="top">Nice and close, sickly green. Leading edge should have been in focus, fading OOF to rear.</td>', 'Nice and close, sickly green. Leading edge should have been in focus, fading OOF to rear.', '2010-03-02 01:26:10.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5886303, 856105, 108580, '<td valign="top">Not everyone''s cup of tea but I appreciate ugly bugs :) Must have some rat DNA!<br/>Nice and close and you got the eyes in focus right up to the schnozz. It won''t score well on DPC unless its an irridescent fly or bee, but it is well taken.</td>', 'Not everyone''s cup of tea but I appreciate ugly bugs :) Must have some rat DNA!Nice and close and you got the eyes in focus right up to the schnozz. It won''t score well on DPC unless its an irridescent fly or bee, but it is well taken.', '2010-03-02 01:27:40.000000', NULL, 1),
(5886309, 856019, 108580, '<td valign="top">Good DOF control and comp. I''d make it a little punchier by using a reflector into the dark areas of the windows of the Lantern and a tighter crop with less distracting BG.</td>', 'Good DOF control and comp. I''d make it a little punchier by using a reflector into the dark areas of the windows of the Lantern and a tighter crop with less distracting BG.', '2010-03-02 01:28:52.000000', NULL, 1),
(5886312, 856253, 108580, '<td valign="top">It''s not obvious that this is a flower in the garden, its a great image but not in the spirit of the challenge. It got a 5.</td>', 'It''s not obvious that this is a flower in the garden, its a great image but not in the spirit of the challenge. It got a 5.', '2010-03-02 01:29:50.000000', NULL, 1),
(5886314, 856306, 108580, '<td valign="top">Lovely textures and PP. I would prefer to see more focused subject than unfocused subject however.</td>', 'Lovely textures and PP. I would prefer to see more focused subject than unfocused subject however.', '2010-03-02 01:30:43.000000', NULL, 1),
(5886328, 856237, 108580, '<td valign="top">Great BG. DOF control. Composition.</td>', 'Great BG. DOF control. Composition.', '2010-03-02 01:34:37.000000', NULL, 1),
(5886330, 856244, 108580, '<td valign="top">Great B&amp;W conversion. Great Shot</td>', 'Great B&W conversion. Great Shot', '2010-03-02 01:35:31.000000', NULL, 1),
(5886335, 856319, 46116, '<td valign="top">Magnificent! 10+</td>', 'Magnificent! 10+', '2010-03-02 01:43:39.000000', NULL, 1),
(5886345, 855815, 101306, '<td valign="top">full of hope and life - beautiful</td>', 'full of hope and life - beautiful', '2010-03-02 01:53:13.000000', NULL, 1),
(5886392, 855872, 93565, '<td valign="top">Detail is exceptional. A deeper DoF would be nice to get at least the foreground antennae in focus, as well as keeping the left midleg/tarsus in the frame.</td>', 'Detail is exceptional. A deeper DoF would be nice to get at least the foreground antennae in focus, as well as keeping the left midleg/tarsus in the frame.', '2010-03-02 03:47:34.000000', NULL, 1),
(5886393, 855620, 93565, '<td valign="top">Great subject isolation.</td>', 'Great subject isolation.', '2010-03-02 03:48:19.000000', NULL, 1),
(5886395, 856293, 93565, '<td valign="top">This looks very last second and hurried. The lighting is very harsh and the subject matter isn''t portrayed in a particularly interesting method. Getting closer to your subject matter and lower, including more just the feet and the area to the right of the person, will make the framing less awkward than cutting them off at the knees.</td>', 'This looks very last second and hurried. The lighting is very harsh and the subject matter isn''t portrayed in a particularly interesting method. Getting closer to your subject matter and lower, including more just the feet and the area to the right of the person, will make the framing less awkward than cutting them off at the knees.', '2010-03-02 03:50:26.000000', NULL, 1),
(5886397, 856273, 93565, '<td valign="top">The badly blown highlights in the sky and pillars really detracts from this shot. A lower perspective might have also added some additional drama to the shot. Generally, shooting from a normal standing height makes photos less-interesting because it''s what we always see.</td>', 'The badly blown highlights in the sky and pillars really detracts from this shot. A lower perspective might have also added some additional drama to the shot. Generally, shooting from a normal standing height makes photos less-interesting because it''s what we always see.', '2010-03-02 03:51:31.000000', NULL, 1),
(5886398, 855463, 93565, '<td valign="top">Very nicely done stock photo. Lighting illuminates the subject well while still keeping texture. Maybe a bit higher saturation to make it look more appetizing, but great job.</td>', 'Very nicely done stock photo. Lighting illuminates the subject well while still keeping texture. Maybe a bit higher saturation to make it look more appetizing, but great job.', '2010-03-02 03:52:58.000000', NULL, 1),
(5886399, 856314, 93565, '<td valign="top">I like the title, and the way the spider is climbing the stick almost makes the title horribly depressing (since it''s a dead-end), but I think this is an interesting shot. I like how the shot has zero background, and the DoF is pretty great.</td>', 'I like the title, and the way the spider is climbing the stick almost makes the title horribly depressing (since it''s a dead-end), but I think this is an interesting shot. I like how the shot has zero background, and the DoF is pretty great.', '2010-03-02 03:54:50.000000', NULL, 1),
(5886400, 856251, 93565, '<td valign="top">Nice change of pace from the rest of the entries. I quite like this. Refreshing, visually interesting, and I''m a sucker for B/W.</td>', 'Nice change of pace from the rest of the entries. I quite like this. Refreshing, visually interesting, and I''m a sucker for B/W.', '2010-03-02 03:56:39.000000', NULL, 1),
(5886405, 855923, 93565, '<td valign="top">If you own that TVR, I''m deeply envious. Is it a Cerbera? My car knowledge is lapsing<br/>Interesting portrayal of cold, but I''m not sure how well it relates to the challenge.</td>', 'If you own that TVR, I''m deeply envious. Is it a Cerbera? My car knowledge is lapsingInteresting portrayal of cold, but I''m not sure how well it relates to the challenge.', '2010-03-02 04:03:02.000000', NULL, 1),
(5886407, 855949, 93565, '<td valign="top">Cool sky, but I don''t know why you went as small as you did. Emphasizing the endless rows of vines a bit more would have worked well for this.</td>', 'Cool sky, but I don''t know why you went as small as you did. Emphasizing the endless rows of vines a bit more would have worked well for this.', '2010-03-02 04:04:13.000000', NULL, 1),
(5886409, 856284, 93565, '<td valign="top">This got a chuckle of out me, for sure, but I''m not going to vote it high based on that. Still, I very much appreciate the effort.</td>', 'This got a chuckle of out me, for sure, but I''m not going to vote it high based on that. Still, I very much appreciate the effort.', '2010-03-02 04:06:23.000000', NULL, 1),
(5886410, 855671, 93565, '<td valign="top">Very surreal desertscape. Looks like a sweet place to visit. I like that you''ve gotten one of the cacti up close to show the viewer what it looks like.</td>', 'Very surreal desertscape. Looks like a sweet place to visit. I like that you''ve gotten one of the cacti up close to show the viewer what it looks like.', '2010-03-02 04:07:45.000000', NULL, 1),
(5886412, 855816, 93565, '<td valign="top">You''ve got some bad artifacting going on in this one.</td>', 'You''ve got some bad artifacting going on in this one.', '2010-03-02 04:10:23.000000', NULL, 1),
(5886413, 856144, 93565, '<td valign="top">A lot of people tried to make the best of the crappy state their garden was, in the offseason, but this entry seems to have done that better than most, and has given some attention to composition.</td>', 'A lot of people tried to make the best of the crappy state their garden was, in the offseason, but this entry seems to have done that better than most, and has given some attention to composition.', '2010-03-02 04:11:53.000000', NULL, 1),
(5886429, 856047, 93565, '<td valign="top">It doesn''t effect my vote, but are those flowers real? More just curious. I like the sepia.<br/>ETA: Taking a look at this again, I also like the background chains or whatever they are. They draw the viewer through things nicely.</td>', 'It doesn''t effect my vote, but are those flowers real? More just curious. I like the sepia.ETA: Taking a look at this again, I also like the background chains or whatever they are. They draw the viewer through things nicely.', '2010-03-02 05:41:28.000000', NULL, 1),
(5886513, 856164, 108580, '<td valign="top">Nice country style shot however the house is cut off and there''s too much front lawn and not enough sky for greater appeal.</td>', 'Nice country style shot however the house is cut off and there''s too much front lawn and not enough sky for greater appeal.', '2010-03-02 08:05:57.000000', NULL, 1),
(5886515, 855274, 108580, '<td valign="top">Interesting perspective, crisp metal, background needs to be more OOF</td>', 'Interesting perspective, crisp metal, background needs to be more OOF', '2010-03-02 08:06:42.000000', NULL, 1),
(5886516, 855382, 108580, '<td valign="top">Yes, very tranquil. Image seems faded, or OE by 1/3 stop or so. The bridge should be more prominent inmo to make the photo stand out.</td>', 'Yes, very tranquil. Image seems faded, or OE by 1/3 stop or so. The bridge should be more prominent inmo to make the photo stand out.', '2010-03-02 08:08:00.000000', NULL, 1),
(5886517, 856181, 108580, '<td valign="top">Crisp and well processed.</td>', 'Crisp and well processed.', '2010-03-02 08:08:16.000000', NULL, 1),
(5886519, 856187, 108580, '<td valign="top">Well spotted. I would try and get the BG more OOF and a tighter crop on the main subject.</td>', 'Well spotted. I would try and get the BG more OOF and a tighter crop on the main subject.', '2010-03-02 08:09:06.000000', NULL, 1),
(5886522, 856083, 108580, '<td valign="top">Main image is dull, probably by design, and the light burst through the c.loud cover adds a Godly touch. Leaves and grass stems entering RHS distracting</td>', 'Main image is dull, probably by design, and the light burst through the c.loud cover adds a Godly touch. Leaves and grass stems entering RHS distracting', '2010-03-02 08:10:34.000000', NULL, 1),
(5886523, 856099, 108580, '<td valign="top">Nice processing of an unusual subject to see on DPC. Background trees distracting and should be more OOF imo. I''d try a higher top down perspective perhaps.</td>', 'Nice processing of an unusual subject to see on DPC. Background trees distracting and should be more OOF imo. I''d try a higher top down perspective perhaps.', '2010-03-02 08:11:43.000000', NULL, 1),
(5886528, 856113, 108580, '<td valign="top">Very soft image, could be the lens? A filter on the lens? Intentional? I would have liked to see this at 12h00 noon with less shadow and dark areas.</td>', 'Very soft image, could be the lens? A filter on the lens? Intentional? I would have liked to see this at 12h00 noon with less shadow and dark areas.', '2010-03-02 08:13:53.000000', NULL, 1),
(5886534, 855923, 108580, '<td valign="top">You''re the Prime Minister? Nice cars they dish out these days :)<br/>Nice crisp photo, good DOF control and exp. Barrel distortion on 18 or so makes the clock tower look like the Tower if Pisa! Bluer sky in PP might have given it more appeal.</td>', 'You''re the Prime Minister? Nice cars they dish out these days :)Nice crisp photo, good DOF control and exp. Barrel distortion on 18 or so makes the clock tower look like the Tower if Pisa! Bluer sky in PP might have given it more appeal.', '2010-03-02 08:15:32.000000', NULL, 1),
(5886540, 856220, 108580, '<td valign="top">Eclectic. Birds were welcome but someone obv. thought you superimposed them due to validation? Crisp image, good sky.</td>', 'Eclectic. Birds were welcome but someone obv. thought you superimposed them due to validation? Crisp image, good sky.', '2010-03-02 08:16:43.000000', NULL, 1),
(5886541, 855942, 108580, '<td valign="top">Great exp and crisp image. Would have tried some fill in flash or reflector on the darker in-shade snail.</td>', 'Great exp and crisp image. Would have tried some fill in flash or reflector on the darker in-shade snail.', '2010-03-02 08:17:26.000000', NULL, 1),
(5886543, 856178, 108580, '<td valign="top">Great macro/close up. Cicada''s are alien looking bugs. Nice colours and your PP is good but not overdone. Great BG.</td>', 'Great macro/close up. Cicada''s are alien looking bugs. Nice colours and your PP is good but not overdone. Great BG.', '2010-03-02 08:18:28.000000', NULL, 1),
(5886549, 855966, 108580, '<td valign="top">Crisp and clear image. Good Comp. Background green blends to much with main subject. 7.</td>', 'Crisp and clear image. Good Comp. Background green blends to much with main subject. 7.', '2010-03-02 08:20:32.000000', NULL, 1),
(5886567, 855416, 108580, '<td valign="top">Simple image yet effective and DMC (Does Meet Challenge). Nice BW and framed reflection.</td>', 'Simple image yet effective and DMC (Does Meet Challenge). Nice BW and framed reflection.', '2010-03-02 08:31:11.000000', NULL, 1),
(5886569, 856263, 108580, '<td valign="top">Nice night shot, I fear a bit UE. Very difficult without fill in flashes to make this work.</td>', 'Nice night shot, I fear a bit UE. Very difficult without fill in flashes to make this work.', '2010-03-02 08:32:02.000000', NULL, 1),
(5886572, 855869, 108580, '<td valign="top">Nice shot. Hope the DNMC don''t crucify you...</td>', 'Nice shot. Hope the DNMC don''t crucify you...', '2010-03-02 08:32:32.000000', NULL, 1),
(5886575, 856152, 108580, '<td valign="top">I Googled but came up with nothing...<br/>Bear Music is playing mind games with us?<br/>Crisp shot, good PP.</td>', 'I Googled but came up with nothing...Bear Music is playing mind games with us?Crisp shot, good PP.', '2010-03-02 08:34:27.000000', NULL, 1),
(5886576, 856240, 108580, '<td valign="top">DMC (Does Meet Challenge). Painting like image...nice</td>', 'DMC (Does Meet Challenge). Painting like image...nice', '2010-03-02 08:35:00.000000', NULL, 1),
(5886577, 855381, 108580, '<td valign="top">Sneaky shot, soft filtering, Gaussian Blur? DMC</td>', 'Sneaky shot, soft filtering, Gaussian Blur? DMC', '2010-03-02 08:35:51.000000', NULL, 1),
(5886579, 856317, 108580, '<td valign="top">A little dark, perhaps some fill in flash might have had more impact.</td>', 'A little dark, perhaps some fill in flash might have had more impact.', '2010-03-02 08:36:21.000000', NULL, 1),
(5886580, 855620, 108580, '<td valign="top">That snail is DOA, KIA! Nice DOF control and colours.</td>', 'That snail is DOA, KIA! Nice DOF control and colours.', '2010-03-02 08:37:07.000000', NULL, 1),
(5886581, 855528, 108580, '<td valign="top">DMC. (Does meet challenge) however not too much going on here to impress, sorry.</td>', 'DMC. (Does meet challenge) however not too much going on here to impress, sorry.', '2010-03-02 08:37:44.000000', NULL, 1),
(5886582, 856124, 108580, '<td valign="top">Pretty succulents. Good DOF control. Busy image and no main subject to really focus on, tell a story however.</td>', 'Pretty succulents. Good DOF control. Busy image and no main subject to really focus on, tell a story however.', '2010-03-02 08:38:42.000000', NULL, 1),
(5886583, 855967, 108580, '<td valign="top">Good lighting, good DOF. BG is suitably OOF to draw attention to main subject.</td>', 'Good lighting, good DOF. BG is suitably OOF to draw attention to main subject.', '2010-03-02 08:39:33.000000', NULL, 1),
(5886585, 855543, 108580, '<td valign="top">Well lit and sharp but uninspiring (to me).</td>', 'Well lit and sharp but uninspiring (to me).', '2010-03-02 08:40:18.000000', NULL, 1),
(5886586, 855662, 108580, '<td valign="top">Great DOF control, not overly inspiring (to me)</td>', 'Great DOF control, not overly inspiring (to me)', '2010-03-02 08:40:52.000000', NULL, 1),
(5886587, 856149, 108580, '<td valign="top">Nice colours, low angled lighting adds depth.</td>', 'Nice colours, low angled lighting adds depth.', '2010-03-02 08:41:14.000000', NULL, 1),
(5886588, 855979, 108580, '<td valign="top">Image OE. Would have preferred more silhouette on the trees.</td>', 'Image OE. Would have preferred more silhouette on the trees.', '2010-03-02 08:41:59.000000', NULL, 1),
(5886590, 855093, 108580, '<td valign="top">Unique subject. Would have preferred less BG clutter from a different angle, top down or low down looking up at subject...</td>', 'Unique subject. Would have preferred less BG clutter from a different angle, top down or low down looking up at subject...', '2010-03-02 08:42:51.000000', NULL, 1),
(5886592, 855519, 108580, '<td valign="top">BG very distracting, despite lens open wide.</td>', 'BG very distracting, despite lens open wide.', '2010-03-02 08:43:30.000000', NULL, 1),
(5886593, 856273, 108580, '<td valign="top">Inviting image, reasonable framing. OE however.</td>', 'Inviting image, reasonable framing. OE however.', '2010-03-02 08:43:56.000000', NULL, 1),
(5886594, 855071, 108580, '<td valign="top">It''s in the garden but I don''t find much appealing, sorry.</td>', 'It''s in the garden but I don''t find much appealing, sorry.', '2010-03-02 08:44:59.000000', NULL, 1),
(5886595, 856219, 108580, '<td valign="top">Texture is good on the spade but the white pot should imo been not in the image at all, it detracts.</td>', 'Texture is good on the spade but the white pot should imo been not in the image at all, it detracts.', '2010-03-02 08:46:00.000000', NULL, 1),
(5886597, 855201, 108580, '<td valign="top">Nice posterity shot, but a tighter crop or close-up and a bunch of snails would have improved this imo.</td>', 'Nice posterity shot, but a tighter crop or close-up and a bunch of snails would have improved this imo.', '2010-03-02 08:46:56.000000', NULL, 1),
(5886599, 856206, 108580, '<td valign="top">Nice title but image lacks a little punch.</td>', 'Nice title but image lacks a little punch.', '2010-03-02 08:47:37.000000', NULL, 1),
(5886601, 855722, 108580, '<td valign="top">Good texture and exp on the stumps. It''s not grabbing me however.</td>', 'Good texture and exp on the stumps. It''s not grabbing me however.', '2010-03-02 08:48:27.000000', NULL, 1),
